# -*- coding: utf-8 -*-
"""Выгрузка слепков с точки — через того же бота, что принимает сделки.

Своего сервера нет, а объезжать ноутбуки и собирать папки руками никто не станет. Канал
остаётся один — Telegram: файл уходит в закрытый чат-архив `sendDocument`-ом, и там он
лежит, сколько нужно, бесплатно.

Выгружаем по умолчанию **эталоны**: это обезличенные слепки по 85 КБ, из которых вычищены
серийники и IMEI, — ровно то, на чём учится разбор журнала Apple. Полные слепки (около
мегабайта, с серийниками) уходят, только если это включили отдельно: в них персональные
данные клиента, и чат для них должен быть соответствующий.

Что уже ушло, помним в простом списке рядом: связи нет — файлы просто подождут и уедут
следующей попыткой, ничего не теряется.
"""
from __future__ import annotations

import glob
import json
import logging
import os

log = logging.getLogger("pintel.tg.upload")

API = "https://api.telegram.org"
ПРЕДЕЛ_ФАЙЛА = 45 * 1024 * 1024          # у Bot API 50 МБ; оставляем запас
ЗА_РАЗ = 20                              # чтобы догон после простоя не занял весь вечер


class ОшибкаВыгрузки(RuntimeError):
    """Человеческий текст, почему файл не ушёл."""


def отправить_файл(токен: str, чат, путь: str, подпись: str = "", имя: str = "",
                   таймаут: float = 120.0) -> int:
    """Файл → сообщение в чате. → message_id. `имя` — под каким именем он ляжет в чат."""
    import httpx
    if not (токен and чат):
        raise ОшибкаВыгрузки("не задан бот или чат для архива")
    размер = os.path.getsize(путь)
    if размер > ПРЕДЕЛ_ФАЙЛА:
        raise ОшибкаВыгрузки(f"{os.path.basename(путь)} — {размер // 1048576} МБ, "
                             "Telegram столько не примет")
    try:
        with open(путь, "rb") as f:
            r = httpx.post(f"{API}/bot{токен}/sendDocument",
                           data={"chat_id": str(чат), "caption": подпись[:1024],
                                 "disable_notification": "true"},
                           files={"document": (имя or os.path.basename(путь), f,
                                               "application/octet-stream")},
                           timeout=таймаут)
        ответ = r.json()
    except Exception as exc:                                     # noqa: BLE001
        raise ОшибкаВыгрузки(f"Telegram не ответил: {exc}") from None
    if not ответ.get("ok"):
        raise ОшибкаВыгрузки("Telegram отказал: " + str(ответ.get("description") or ответ))
    return int((ответ.get("result") or {}).get("message_id") or 0)


def _прочитать_список(путь: str) -> set:
    try:
        with open(путь, encoding="utf-8") as f:
            return set(json.load(f).get("ушло") or [])
    except Exception:                                            # noqa: BLE001 — нет файла или битый
        return set()


def _записать_список(путь: str, имена) -> None:
    try:
        os.makedirs(os.path.dirname(путь), exist_ok=True)
        with open(путь, "w", encoding="utf-8") as f:
            # храним только последние: старые файлы всё равно удаляет уборка
            json.dump({"ушло": sorted(имена)[-3000:]}, f, ensure_ascii=False)
    except OSError as e:
        log.warning("архив: список отправленного не сохранился: %s", e)


def догнать(токен: str, чат, папка: str, отметка: str, маска: str = "*.zip",
            подпись: str = "", за_раз: int = ЗА_РАЗ) -> dict:
    """Отправить всё, что ещё не уходило. → {ушло, осталось, ошибка}.

    Связи нет — не беда: файлы останутся на диске и уедут в следующий раз. Поэтому список
    отправленного пополняется по одному файлу, а не в конце.
    """
    if not (токен and чат):
        return {"ушло": 0, "осталось": 0, "ошибка": ""}
    было = _прочитать_список(отметка)
    файлы = sorted(glob.glob(os.path.join(папка, маска)), key=os.path.getmtime)
    # ключ — путь относительно папки, а не имя файла: у полных слепков все файлы
    # называются snapshot.json, и по имени они схлопнулись бы в один
    ключ = lambda p: os.path.relpath(p, папка).replace(os.sep, "/")
    ждут = [p for p in файлы if ключ(p) not in было]
    ушло, беда = 0, ""
    for путь in ждут[:за_раз]:
        имя = ключ(путь).replace("/", "_")
        try:
            отправить_файл(токен, чат, путь, f"{подпись} · {имя}" if подпись else имя, имя=имя)
        except ОшибкаВыгрузки as exc:
            текст = str(exc)
            if "столько не примет" in текст:                     # большой файл не ждёт починки
                было.add(ключ(путь))
                _записать_список(отметка, было)
                log.warning("архив: %s пропущен — %s", имя, текст)
                continue
            беда = текст                                         # нет связи: дальше не идём
            break
        было.add(ключ(путь))
        _записать_список(отметка, было)
        ушло += 1
    осталось = len([p for p in файлы if ключ(p) not in было])
    if ушло:
        log.info("архив: ушло %s, осталось %s", ушло, осталось)
    return {"ушло": ушло, "осталось": осталось, "ошибка": беда}
